"""
    Function- uvm_object_value_str

    Args:
        v (object): Object to convert to string.
    Returns:
        str: Inst ID for `UVMObject`, otherwise uses str()
    """
def uvm_object_value_str(v: Any) -> object {
    if (v is None) {
        return "<null>";
    }
    res = "";
    if hasattr(v, 'get_inst_id') {
        res = "{}".format(v.get_inst_id());
        res = "@" + res;
    } else {
        res = str(v);
    }
    return res;
}

"""
    Combine the image paths from `center`, `left` and `right` using the correction factor `correction`
    Returns ([image_paths], [measurements])
    """
def combine_images(
    center: Any, left: Any, right: Any, measurement: Any, correction: Any
) -> object {
    image_paths = [];
    image_paths.extend(center);
    image_paths.extend(left);
    image_paths.extend(right);
    measurements = [];
    measurements.extend(measurement);
    measurements.extend([(x + correction) for x in measurement]);
    measurements.extend([(x - correction) for x in measurement]);
    return (image_paths, measurements);
}

"""Get the ring_size of apply an operation on two values

    Args:
        x_ring_size (int): the ring size of op1
        y_ring_size (int): the ring size of op2

    Returns:
        The ring size of the result
    """
def get_ring_size(x_ring_size: int, y_ring_size: int) -> int {
    if (x_ring_size != y_ring_size) {
        raise ValueError(
            "Expected the same ring size for x and y ({x_ring_size} vs {y_ring_size})"
        );
    }
    return x_ring_size;
}

"""Find the tier for the given endurance volume (IOPS per GB)

    :param volume: The volume for which the tier level is desired
    :return: Returns a float value indicating the IOPS per GB for the volume
    """
def find_endurance_tier_iops_per_gb(volume: Any) -> object {
    tier_description_split = volume['storageTierLevel']['description'].split();
    if (tier_description_split != []) {
        iops_per_gb = tier_description_split[0];
        if (iops_per_gb == '0.25') {
            return 0.25;
        }
        if (iops_per_gb == '2') {
            return 2.0;
        }
        if (iops_per_gb == '4') {
            return 4.0;
        }
        if (iops_per_gb == '10') {
            return 10.0;
        }
    }
    raise ValueError("Could not find tier IOPS per GB for this volume");
}

